<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/../config/mailer.php';$db=db();$msg='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['log_communication'])){$q=$db->prepare('INSERT INTO client_communications(client_id,project_id,ticket_id,staff_id,channel,subject,message,direction,occurred_at) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$_POST['client_id']?:null,$_POST['project_id']?:null,$_POST['ticket_id']?:null,$_POST['staff_id']?:null,$_POST['channel'],trim($_POST['subject']??''),trim($_POST['message']??''),$_POST['direction'],$_POST['occurred_at']?:date('Y-m-d H:i:s')]);$msg='Communication logged.';}$templates=$db->query('SELECT * FROM email_templates ORDER BY name')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['send_email'])){$leadId=(int)($_POST['lead_id']??0);$templateId=(int)($_POST['template_id']??0);$stmt=$db->prepare('SELECT l.*,t.* FROM leads l JOIN email_templates t ON t.id=? WHERE l.id=? AND t.is_active=1 LIMIT 1');$stmt->execute([$templateId,$leadId]);$row=$stmt->fetch();if(!$row){$error='Lead or email template not found.';}elseif(!filter_var($row['email'],FILTER_VALIDATE_EMAIL)){$error='Lead does not have a valid email address.';}else{$vars=['{{client_name}}'=>$row['name'],'{{company}}'=>$row['company']??'','{{service}}'=>$row['service']??'','{{estimated_value}}'=>$row['estimated_value']??'','{{website_url}}'=>defined('APP_URL')?APP_URL:''];$subject=strtr($row['subject'],$vars);$body=strtr($row['body_html'],$vars);$ins=$db->prepare("INSERT INTO email_logs (lead_id,template_id,recipient_email,subject,status) VALUES (?,?,?,?, 'queued')");$ins->execute([$leadId,$templateId,$row['email'],$subject]);$logId=(int)$db->lastInsertId();$result=send_smtp_email($row['email'],$subject,$body);if($result['success']){$db->prepare("UPDATE email_logs SET status='sent',sent_at=NOW() WHERE id=?")->execute([$logId]);$db->prepare("INSERT INTO lead_activities (lead_id,activity_type,subject,description) VALUES (?,?,?,?)")->execute([$leadId,'email',$subject,'Email sent to '.$row['email']]);$msg='Email sent successfully.';}else{$db->prepare("UPDATE email_logs SET status='failed',error_message=? WHERE id=?")->execute([$result['error'],$logId]);$error='Email failed: '.$result['error'];}}}$logs=$db->query('SELECT e.*,l.name FROM email_logs e LEFT JOIN leads l ON l.id=e.lead_id ORDER BY e.created_at DESC LIMIT 50')->fetchAll();$leads=$db->query("SELECT id,name,email,service FROM leads WHERE email IS NOT NULL AND email<>'' AND status NOT IN ('won','lost') ORDER BY created_at DESC LIMIT 100")->fetchAll();$clients=$db->query('SELECT id,name FROM clients ORDER BY name')->fetchAll();$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$dt=static fn($v):string=>$v?date('d M Y, H:i',strtotime((string)$v)):'—';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Communication Center</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:1150px"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2">Communication Center</h1><p class="text-muted mb-0">Send and track CRM emails and client communications</p></div></div><?php if($msg):?><div class="alert alert-success"><?=$esc($msg)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=$esc($error)?></div><?php endif;?><div class="card border-0 shadow-sm p-4 mb-4"><h2 class="h5">Log Client Communication</h2><form method="post" class="row g-3"><input type="hidden" name="log_communication" value="1"><div class="col-md-3"><select name="client_id" class="form-select"><option value="">Client</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=$esc($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><select name="channel" class="form-select"><option>email</option><option>phone</option><option>whatsapp</option><option>meeting</option><option>portal</option><option>internal</option></select></div><div class="col-md-2"><select name="direction" class="form-select"><option>outbound</option><option>inbound</option><option>internal</option></select></div><div class="col-md-5"><input name="subject" class="form-control" placeholder="Subject"></div><div class="col-12"><textarea name="message" class="form-control" rows="3" placeholder="Message / notes"></textarea></div><div class="col-md-4"><input type="datetime-local" name="occurred_at" class="form-control"></div><div class="col-md-8"><button class="btn btn-dark">Log Communication</button></div></form></div><div class="card border-0 shadow-sm p-4 mb-4"><h2 class="h5">Send Email</h2><form method="post" class="row g-3"><input type="hidden" name="send_email" value="1"><div class="col-md-6"><select name="lead_id" class="form-select" required><option value="">Select lead</option><?php foreach($leads as $l):?><option value="<?=$l['id']?>"><?=$esc($l['name'])?> — <?=$esc($l['email'])?></option><?php endforeach;?></select></div><div class="col-md-6"><select name="template_id" class="form-select" required><option value="">Select template</option><?php foreach($templates as $t):?><option value="<?=$t['id']?>"><?=$esc($t['name'])?></option><?php endforeach;?></select></div><div class="col-12"><button class="btn btn-dark">Send Email</button></div></form></div><div class="card border-0 shadow-sm p-4"><h2 class="h5">Email History</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Lead</th><th>Recipient</th><th>Subject</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?=$esc($l['name']?:'—')?></td><td><?=$esc($l['recipient_email'])?></td><td><?=$esc($l['subject'])?></td><td><?=$esc($l['status'])?></td><td><?=$esc($dt($l['sent_at']?:$l['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>